# background ==================================================================

# Here we extract orthologs from emapper output.

# Steps:
# - cr to mm orthologs
#   - get cr to mm orthologs from the cr emapper output (at protein level)
#   - add cr and mm gene ids to this table
#   - only keep the gene id columns and get rid of protein id columns as well as
#     orth_type information (this was likely generated by emapper at the
#     protein level; we will recreate this at the gene level)
#   - keep distinct rows
# - based on the gene_ids, recreate orth_types

# setup =======================================================================
library(tidyverse)
library(here)

crdir <- here("species/crob/refseq_KH")
mmdir <- here("species/mmus/genome/GRCm39/106")

# data ========================================================================
cr <- read_tsv(
  here(crdir, "results/emapper/out/out.emapper.orthologs"),
  comment = "##"
) %>%
  rename(query = `#query`)

cr_genes <- read_tsv(here(crdir, "results/genes/gid-pid_mapping.tsv"))
mm_genes <- read_csv(here(mmdir, "results/genes/gid-pid-mapping.csv"))

# make column ids consistent for joining
cr_genes <- cr_genes %>%
  rename_with(function(x) paste0("cr_", x))
mm_genes <- mm_genes %>%
  rename(symbol = gene_symbol) %>%
  rename_with(function(x) paste0("mm_", x))

# remove gid and pid version numbers for mouse
mm_genes <- mm_genes %>%
  mutate(
    mm_gene_id = str_remove(mm_gene_id, "\\.\\d+"),
    mm_protein_id = str_remove(mm_protein_id, "\\.\\d+")
  )

# crob to mmus orthologs ======================================================
cr <- cr %>%
  filter(species == "Mus musculus(10090)") %>%
  # 1 ortholog per row
  mutate(orthologs = str_split(orthologs, ",")) %>%
  unnest(orthologs) %>%
  # clean up
  mutate(orthologs = str_remove(orthologs, "^\\*"))

# add gene ids and remove other columns
cr_to_mm <- cr %>%
  rename(cr_protein_id = query, mm_protein_id = orthologs) %>%
  left_join(
    select(cr_genes, cr_gene_id, cr_protein_id),
    by = "cr_protein_id"
  ) %>%
  filter(!is.na(cr_gene_id)) %>%
  left_join(
    select(mm_genes, mm_gene_id, mm_protein_id),
    by = "mm_protein_id"
  ) %>%
  filter(!is.na(mm_gene_id)) %>%
  select(cr_gene_id, mm_gene_id) %>%
  distinct()

# assign orthology types ======================================================
orth <- cr_to_mm %>%
  nest(.by = cr_gene_id) %>%
  mutate(n_mmus = map_int(data, ~ length(unique(.x$mm_gene_id)))) %>%
  mutate(
    cr_orth_type = case_when(
      n_mmus == 1 ~ "one2one",
      n_mmus > 1 ~ "one2many"
    )
  ) %>%
  unnest(data) %>%
  nest(.by = mm_gene_id) %>%
  mutate(n_crob = map_int(data, ~ length(unique(.x$cr_gene_id)))) %>%
  mutate(
    mm_orth_type = case_when(
      n_crob == 1 ~ "one2one",
      n_crob > 1 ~ "one2many"
    )
  ) %>%
  unnest(data) %>%
  mutate(
    orth_type = case_when(
      cr_orth_type == "one2many" & mm_orth_type == "one2many" ~ "many2many",
      cr_orth_type == "one2many" & mm_orth_type == "one2one" ~ "one2many",
      cr_orth_type == "one2one" & mm_orth_type == "one2many" ~ "many2one",
      cr_orth_type == "one2one" & mm_orth_type == "one2one" ~ "one2one"
    )
  ) %>%
  select(cr_gene_id, mm_gene_id, orth_type)

# add mouse symbols ===========================================================

orth <- left_join(
  orth,
  (mm_genes %>%
    select(mm_gene_id, mm_symbol) %>%
    distinct()),
  by = "mm_gene_id"
)

# write results ===============================================================
write_csv(
  orth,
  here(crdir, "results/emapper/processed/emapper_orthologs_mouse.csv")
)

# end =========================================================================
